  "implementation": "def solve(case):
    import json
    payload = case['payload']
    nodes = payload['nodes']
    required = payload['required_symbols']
    required_set = set(required)
    node_map = {n['id']: n for n in nodes}
    children = {}
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            children.setdefault(pid, []).append(n['id'])
    # Build lists
    removable = [n for n in nodes if n['removable']]
    # sort by depth descending, then id ascending (stable tie break)
    removable.sort(key=lambda x: (-x['depth'], x['id']))
    retained = set(n['id'] for n in nodes)
    removed = set()
    removal_order = []
    # initial symbol counts
    symbol_count = {}
    for n in nodes:
        sym = n['symbol']
        symbol_count[sym] = symbol_count.get(sym, 0) + 1
    def can_remove(node):
        # root not removable (removable=False anyway)
        if node['parent'] is None:
            return False
        # must not have retained children
        for cid in children.get(node['id'], []):
            if cid in retained:
                return False
        # check required symbols still represented after removal
        sym = node['symbol']
        if sym in required_set and symbol_count.get(sym, 0) == 1:
            return False
        return True
    for node in removable:
        nid = node['id']
        if nid in removed:
            continue
        if can_remove(node):
            removed.add(nid)
            retained.discard(nid)
            symbol_count[node['symbol']] -= 1
            removal_order.append(nid)
    # sort retained IDs by id string
    sorted_retained = sorted(retained)
    return {'retained': sorted_retained, 'removal_order': removal_order}"
